style.css:
@-moz-document regexp("https?://(?!donate\.|blog\.|support\.)([a-z0-9-]+\.)*khanacademy\.org(/.*)?") {
:root { color-scheme: dark !important; }

  /* Wonder Blocks design tokens — retoning these re-themes the bulk of the app;
     learning/mastery/brand tokens stay as Khan sets them. `body` and `[data-wb-theme]`
     MUST stay in the selector: Khan re-declares the whole light palette on `body` and
     again on the `thunderblocks` shell wrapper, and a property on a closer ancestor beats
     an inherited one however `!important`. */
  :root, body, [data-wb-theme] {
    /* Surfaces */
    --wb-semanticColor-core-background-base-default: #14181d !important;
    --wb-semanticColor-core-background-base-subtle: #1c2128 !important;
    --wb-semanticColor-core-background-base-strong: #0d1117 !important;
    --wb-semanticColor-core-background-disabled-default: #1c2128 !important;
    --wb-semanticColor-core-background-disabled-strong: #262c33 !important;
    --wb-semanticColor-core-background-neutral-subtle: #1c2128 !important;
    --wb-semanticColor-feedback-neutral-subtle-background: #1c2128 !important;
    --wb-semanticColor-status-neutral-background: #1c2128 !important;
    --wb-semanticColor-chonky-disabled-background-primary: #1c2128 !important;
    --wb-semanticColor-chonky-disabled-background-secondary: #1c2128 !important;

    /* Inputs */
    --wb-semanticColor-input-default-background: #1a1f26 !important;
    --wb-semanticColor-input-readOnly-background: #1a1f26 !important;
    --wb-semanticColor-input-disabled-background: #181c22 !important;
    --wb-semanticColor-input-default-border: #3a424c !important;
    --wb-semanticColor-input-readOnly-text: #c4cdd6 !important;
    --wb-semanticColor-input-disabled-foreground: #717880 !important;

    /* Subtle blue "info / notice" tints used for banners + selected nav */
    --wb-semanticColor-feedback-info-subtle-background: #18222f !important;
    --wb-semanticColor-status-notice-background: #18222f !important;
    --wb-semanticColor-core-background-instructive-subtle: #18222f !important;
    --wb-semanticColor-chonky-progressive-background-secondary-rest: #18222f !important;
    --wb-semanticColor-chonky-progressive-background-secondary-hover: #1d2a3a !important;
    --wb-semanticColor-chonky-progressive-background-secondary-press: #1d2a3a !important;
    --wb-semanticColor-chonky-progressive-background-secondary-selected: #1d2a3a !important;

    /* Text. Khan's ink scale runs strong (darkest) -> subtle (lightest), so on dark it must
       run the other way. `default` is also the fill of the progress grid's Quiz/Unit-test
       mask glyphs, where a too-dark value shows first. */
    --wb-semanticColor-core-foreground-neutral-strong: #e6edf3 !important;
    --wb-semanticColor-core-foreground-neutral-default: #c4cdd6 !important;
    --wb-semanticColor-core-foreground-neutral-subtle: #9aa4af !important;
    --wb-semanticColor-feedback-neutral-subtle-text: #c4cdd6 !important;
    --wb-semanticColor-feedback-info-subtle-text: #c4cdd6 !important;
    --wb-semanticColor-status-neutral-foreground: #c4cdd6 !important;
    --wb-semanticColor-input-error-foreground: #e6edf3 !important;

    /* Borders. The `subtle` tone is Khan's hairline colour, drawn as inset box-shadows
       and SVG strokes no border-color rule can reach. */
    --wb-semanticColor-core-border-neutral-subtle: #2d333b !important;
    --wb-semanticColor-core-border-neutral-default: #2d333b !important;
    --wb-semanticColor-core-border-neutral-strong: #3a424c !important;
    --wb-semanticColor-chonky-neutral-border-secondary-rest: #2d333b !important;
    --wb-semanticColor-chonky-neutral-border-secondary-hover: #3a424c !important;
    --wb-semanticColor-feedback-neutral-subtle-border: #2d333b !important;
    --wb-semanticColor-core-shadow-chonky-neutral-subtle: #2d333b !important;

    /* Brand blue refined: the raw #1865f2 glows harshly on near-black. */
    --wb-semanticColor-core-foreground-instructive-default: #5fb0e6 !important;
    --wb-semanticColor-core-foreground-instructive-strong: #9bd4ff !important;
    --wb-semanticColor-chonky-progressive-foreground-secondary-rest: #5fb0e6 !important;
    --wb-semanticColor-action-secondary-progressive-hover-foreground: #9bd4ff !important;
    --wb-semanticColor-status-notice-foreground: #5fb0e6 !important;
    /* `link-rest` is the token Wonder Blocks' inline links read (`link-hover` covers
       only hover), applied through a hashed class the un-important `a { color }` rule
       below cannot reach. */
    --wb-semanticColor-link-rest: #5fb0e6 !important;
    --wb-semanticColor-link-hover: #9bd4ff !important;

    /* Primary CTAs keep the Khan blue, deepened so white button text reads clean. */
    --wb-semanticColor-action-primary-progressive-default-background: #2563c9 !important;
    --wb-semanticColor-action-primary-progressive-hover-background: #2f6fd6 !important;
    --wb-semanticColor-action-primary-progressive-press-background: #1d51b0 !important;
    --wb-semanticColor-core-background-instructive-default: #2563c9 !important;
    --wb-semanticColor-core-background-instructive-strong: #1d51b0 !important;

    /* Mastery: gold "attempted" and green "complete" carry meaning and stay; only the
       empty "not started" square is darkened. */
    --wb-semanticColor-learning-background-progress-notStarted-default: #2d333b !important;
    --wb-semanticColor-learning-foreground-progress-notStarted-strong: #8b949e !important;

    /* Worked-example term highlights. MathJax articles colour each term through
       `color: var(--wb-semanticColor-learning-math-foreground-<hue>, #hex)` on an <mjx-mstyle>,
       so the token is what renders; the literal-colour rules further down only reach the
       `mathcolor` / inline-rgb carriers. Same lifted hues as that block so both renderers pair.
       `grayH` / `grayI` are near-black inks, not highlights. */
    --wb-semanticColor-learning-math-foreground-blue: #6cb6d9 !important;
    --wb-semanticColor-learning-math-foreground-gold: #e3b341 !important;
    --wb-semanticColor-learning-math-foreground-gray: #9aa4af !important;
    --wb-semanticColor-learning-math-foreground-grayH: #c4cdd6 !important;
    --wb-semanticColor-learning-math-foreground-grayI: #e6edf3 !important;
    --wb-semanticColor-learning-math-foreground-green: #7ee787 !important;
    --wb-semanticColor-learning-math-foreground-pink: #ff8ac4 !important;
    --wb-semanticColor-learning-math-foreground-purple: #d2a8ff !important;
    --wb-semanticColor-learning-math-foreground-purpleD: #d2a8ff !important;
    --wb-semanticColor-learning-math-foreground-red: #ff7b72 !important;
  }

  /* Base surfaces */
  html, body { background-color: #14181d !important; color: #c4cdd6 !important; }

  /* Legacy "bibliotron" page shell. Not a header despite the name: `.white-outer-wrapper`
     is the sheet the WHOLE page sits on, `#main-content` included, so it takes the base
     background. */
  .bibliotron-header,
  .white-outer-wrapper,
  .clearfix.bibliotron-header { background-color: #14181d !important; }
  /* The shell hardcodes light-page ink on its text. Also covers the header wordmark,
     "Donate" and "Log in" — the nav is inside the shell. */
  .bibliotron-header a,
  .bibliotron-header span,
  .bibliotron-header div { color: #e6edf3 !important; }
  /* The shell wraps the WHOLE page, so restore link colour inside the content area only.
     Only genuine inline links carry a direct text node; cards, rows and tiles wrap their
     label in a child element the shell rule still paints, so their titles stay
     near-white. */
  #main-content a { color: #5fb0e6 !important; }
  #main-content a:hover { color: #9bd4ff !important; }
  /* Wonder Blocks draws a link's leading/trailing glyph as an EMPTY <span> whose
     `mask-image` is filled by its own `background-color: currentColor`, so the shell's
     `span` rule would split one component into two colours. `> span:empty` is the exact
     shape of a mask icon: label spans have text, and the mastery-grid icon spans are
     grandchildren. */
  #main-content a > span:empty { color: inherit !important; }
  /* A prose link's label is often a <span> the shell's `span` rule would pin near-white
     beside a blue anchor. Scoped to `p a` so lesson-row / card links keep near-white
     titles; `a[data-kind="primary"] span` below out-specifies it. */
  #main-content p a > span { color: inherit !important; }
  /* The unit page's lesson-section title is an <h2> whose ONLY child is a link with a direct
     text node, so the content-link rule paints a 24px heading link-blue where Khan draws it in
     the heading ink. Stable test id; the hover arm is restated because this rule ties the
     `a:hover` above and would otherwise erase the cue. */
  #main-content a[data-testid="lesson-card-link"] { color: #e6edf3 !important; }
  #main-content a[data-testid="lesson-card-link"]:hover { color: #9bd4ff !important; }
  /* `tertiary` IS a link rendered as a button, so give back the brand blue the shell's
     span rule flattens. `#main-content button[aria-expanded]` (home accordions) is more
     specific and stays near-white. */
  button[data-kind="tertiary"],
  button[data-kind="tertiary"] span { color: #5fb0e6 !important; }
  button[data-kind="tertiary"]:hover,
  button[data-kind="tertiary"]:hover span { color: #9bd4ff !important; }

  /* Top nav. `#top-header-container` is the full-bleed strip; the inner `nav` is
     width-capped, so theming only the nav leaves brand-navy shoulders. */
  nav[role="navigation"], header[role="banner"],
  #top-header-container { background-color: #0d1117 !important; }

  /* Header wordmark, monochrome variant: the leaf is knocked out of the hexagon in a
     hardcoded `#ffffff` over the `neutral-strong` ink — white on white once that ink flips
     light. Only this variant matches; the classic logo fills its hexagon brand green with
     no `neutral-strong` sibling before the leaf. */
  [aria-label="Khan Academy"] path[fill*="neutral-strong"] + path[fill="#ffffff"] {
    fill: #0d1117 !important;
  }

  /* Global footer: the same brand navy as the header strip and otherwise unreached, so
     it would be the brightest large surface. */
  footer[class] { background-color: #0d1117 !important; }

  /* "Explore" mega-menu. A floating surface, so it needs a SOLID background —
     `transparent` would let the page scroll through it. Its hover/focus state and column
     divider are hardcoded light. */
  #header-dropdown [data-testid="learn-menu"] { background-color: #1c2128 !important; }
  [data-testid="learn-menu"] > ul + div { background-color: #2d333b !important; }
  [data-testid="learn-menu"] a:hover, [data-testid="learn-menu"] button:hover,
  [data-testid="learn-menu"] a:focus, [data-testid="learn-menu"] button:focus {
    background-color: #232a32 !important;
  }

  /* Mobile hamburger drawer: a body-level region outside `#main-content` with a hardcoded
     white panel and rows, so neither the token remaps nor the neutralizer reach it. */
  #page-header-responsive-nav-menu { background-color: #1c2128 !important; }
  #page-header-responsive-nav-menu [class] { background-color: transparent !important; }
  #page-header-responsive-nav-menu a:hover,
  #page-header-responsive-nav-menu button:hover { background-color: #232a32 !important; }

  /* "NEW" pill: a pale blue chip whose label inherits the remapped near-white text.
     Stable test id. */
  [data-testid="new-pill"] { background-color: #18222f !important; }
  [data-testid="new-pill"] * {
    color: #9bd4ff !important; -webkit-text-fill-color: #9bd4ff !important;
  }

  /* Skip-to-main-content link: hidden until keyboard focus, then paints a hardcoded
     white panel. Stable id. */
  #triggerless-modal-focus-anchor {
    background-color: #1c2128 !important;
    color: #5fb0e6 !important;
  }

  /* Wonder Blocks tooltips render into a body-level portal, escaping every
     `#main-content` rule, and keep a hardcoded white bubble. The tail is an <svg>
     polyline, not a CSS border triangle, so it needs its own fill. */
  [role="tooltip"] { color: #e6edf3 !important; }
  [role="tooltip"] > div { background-color: #1c2128 !important; }
  [role="tooltip"] svg polyline { fill: #1c2128 !important; }

  /* Wonder Blocks links hardcode the raw brand blue through a class, and the plain
     `a { color }` rule below is deliberately un-important so brand CTAs keep their colour
     — leaving 3.55:1 on a dark modal. */
  [role="dialog"] a { color: #9bd4ff !important; }

  /* Deliberately left alone: the onboarding dialog's lavender band. Its mastery bar is an
     OPAQUE raster gif with that lavender baked in, so darkening the container only yields a
     two-tone band. */

  /* Notification banner: hardcodes the pale info blue outside `#main-content`; keyed on
     its stable ARIA contract, not a hashed class. Restore its 6px brand-blue accent against
     the blanket border reset — LEFT EDGE ONLY: at narrow widths Khan's border is transparent
     on all four sides, which the reset would turn into a grey box. */
  [role="status"][aria-label="Notification Banner"] {
    background-color: #18222f !important;
    border-color: transparent !important;
    border-left-color: #5fb0e6 !important;
  }
  [role="status"][aria-label="Notification Banner"] a { color: #9bd4ff !important; }

  /* The logged-out sign-up promo also mounts as a SIBLING of `#main-content`, in
     `#above-main-content-portal`, which the neutralizer never reaches; that portal carries
     this promo alone, so it is keyed on the id. `data-kind` rather than `button[class]`: the
     audience pills are `secondary` (natively white-filled) and the dismiss X `tertiary`
     (natively transparent). */
  #above-main-content-portal {
    background-color: #14181d !important;
    background-image: none !important;
  }
  #above-main-content-portal [class]:not(span) {
    background-color: transparent; background-image: none;
  }
  /* The element type here is load-bearing: without it the selector is one step LESS
     specific than the `[class]:not(span)` neutralizer above and the fill never
     paints. */
  #above-main-content-portal button[data-kind="secondary"],
  #above-main-content-portal a[data-kind="secondary"] { background-color: #1c2128; }
  #above-main-content-portal button[data-kind="secondary"]:hover,
  #above-main-content-portal a[data-kind="secondary"]:hover { background-color: #232a32; }
  #above-main-content-portal button > span:first-child:empty {
    background-color: #c4cdd6 !important;
  }

  /* The home donation takeover is a SIBLING of `#main-content`, so the neutralizer misses
     it. The gift form keeps its fills from the `form fieldset` and `[data-kind="primary"]`
     rules below. `:not(span)` for the usual reason — icon spans are mask-images whose FILL
     is their background-color. */
  #donate-banner { background-color: #14181d !important; }
  #donate-banner [class]:not(span) { background-color: transparent; }
  /* `#donate-banner` is a 0-height wrapper whose only child is an ABSOLUTELY POSITIONED
     full-bleed panel lying over the page content everywhere but home. Natively opaque, so
     it must stay opaque here. */
  #donate-banner > div { background-color: #14181d !important; }

  /* Headings + body text. Khan ships dark-on-light copy through hardcoded atomic colour
     classes that bypass the tokens; inline-coloured spans keep their colour via the
     rules below. */
  h1, h2, h3, h4, h5, h6 { color: #e6edf3 !important; }
  /* Bare <b>: Khan hardcodes the hero stat figures WITH a matching
     `-webkit-text-fill-color`, so `color` alone would not stick. That fill INHERITS and
     overrides `color` on every descendant, so every rule recolouring a term inside a bold
     run must set the fill too — the math remaps below all do. */
  b, strong { color: #e6edf3 !important; -webkit-text-fill-color: #e6edf3 !important; }
  /* …but a bold run INSIDE a link is part of the link, and the rule above outranks every
     un-important link colour; Khan's CMS bolds some list entries and not others, which would
     render one list in two colours. `currentColor` rather than `inherit` so the fill tracks
     the anchor's resolved colour; a coloured marketing card (a class selector) still wins. */
  a b, a strong { color: inherit !important; -webkit-text-fill-color: currentColor !important; }
  /* Home audience tablist: all three labels hardcoded to the light-page ink (+
     text-fill), with no native colour difference between states, so lift all three. */
  #teachers-tab, #students-tab, #parents-tab {
    color: #e6edf3 !important; -webkit-text-fill-color: #e6edf3 !important;
  }
  /* Home "Explore" grid: each category header's label is a direct text node hardcoded
     near-black. Stable scope: the only aria-expanded buttons under #main-content. */
  #main-content button[aria-expanded] { color: #e6edf3 !important; }
  p, li, label, dd, dt, blockquote, figcaption, td, th, caption,
  legend, article, section, main { color: #c4cdd6 !important; }
  span:not([class*="color"]):not([style*="color"]) { color: inherit; }

  /* Links — keep Khan blue identity, refined for dark */
  a { color: #5fb0e6; }
  a:hover { color: #9bd4ff; }

  /* Exercise "Report a problem" button: label hardcoded to a dark navy. Scoped to the
     stable exercise-chrome wrapper, its only button. */
  .exercise-chrome-content-for-mobile-zoom button { color: #9aa4af !important; }
  .exercise-chrome-content-for-mobile-zoom button:hover { color: #c4cdd6 !important; }

  /* "Draw on exercise" overlay: `[data-testid="drawing-area"]` lays a transparent SVG over
     the problem, and its strokes take the light-page ink #21242c by default, from a palette
     of black / red / gold / green / teal / blue / purple. Only a filter reaches the pattern
     fill the strokes are painted through; transparent pixels stay transparent, so the page
     shows through unchanged. The swatch is the wrapper DIV of the opacity-0 colour input
     (hashed, so it degrades to a mismatched swatch, not a lost stroke). */
  [data-testid="drawing-area"],
  [role="toolbar"][aria-label="Drawing controls"] ._a7ipt1d {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Discussion tabs: active (brand blue) and inactive (mid grey) hardcoded through
     `-webkit-text-fill-color`. Stable ARIA tab ids; set the fill too, since it drives
     the rendered colour. */
  /* The video page's "About" / "Transcript" tabs are a second tablist with the same
     palette and text-fill trick. */
  #questions-tab, #comments-tab,
  #videoTabAbout-tab, #videoTabTranscript-tab {
    color: #9aa4af !important; -webkit-text-fill-color: #9aa4af !important;
  }
  #questions-tab[aria-selected="true"], #comments-tab[aria-selected="true"],
  #videoTabAbout-tab[aria-selected="true"], #videoTabTranscript-tab[aria-selected="true"] {
    color: #5fb0e6 !important; -webkit-text-fill-color: #5fb0e6 !important;
  }

  /* Search box (header) — white-on-white in light theme */
  input[type="search"],
  input[type="text"],
  input[type="email"],
  input[type="password"],
  input[type="number"],
  input[type="tel"],
  input[type="url"],
  textarea,
  input[placeholder*="earch"] {
    background-color: #1a1f26 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  input::placeholder, textarea::placeholder { color: #8b949e !important; opacity: 1 !important; }

  /* Collapsed header search: a Wonder Blocks `secondary` BUTTON that expands into a real
     input, not an <input>, and outside `#main-content` — so neither the input rules above nor
     the neutralizer reach it. */
  [data-testid="navbar-search-button"] {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
  }
  [data-testid="navbar-search-button"]:hover { background-color: #232a32 !important; }

  /* Marketing site (/about, /about/*, /teachers, /schools). Webflow: no `#main-content`, no
     design token, no hashed class, so nothing above reaches it except the global text block.
     Only SURFACES need work — the ink layer is inherited, and nothing here paints a
     background-image.
     The pale surfaces are a CLOSED set of stable author-written Webflow classes, listed
     explicitly rather than swept blanket-style: a sweep also erases the purple active-tab
     underline (`.tab_button_line`), the coloured stat cards and the CTA fills, the only
     colour these pages carry. `.card_icon_circle` and `.graphic_shape_wrap` are left alone
     for the same reason. Header and mega-menu panels must stay opaque; the tab module's
     cards must keep reading as cards. */
  .page_wrap, section.u-section { background-color: #14181d !important; }
  /* `.nav_mobile_layout` is the narrow-width twin of the desktop bar, a separate white
     strip. */
  .nav_desktop_contain, .nav_mobile_layout { background-color: #0d1117 !important; }
  /* The announcement strip's whole content is ONE indigo ink — link, trailing arrow
     (`stroke="currentColor"`) and X — but the plain `a { color }` rule reaches only the
     link. */
  .nav_banner_wrap { background-color: #18222f !important; }
  .nav_banner_wrap, .nav_banner_wrap * { color: #9bd4ff !important; }
  /* That strip's full text lives in a `<dialog class="modal_dialog">`, `display:none` until
     clicked; `.modal_backdrop` is already a near-black scrim. The X is a
     `stroke: currentColor` <svg> whose ink Webflow sets on the wrapper and serialises as
     `color(srgb …)`, so the stroke is restated on the path too. Both classes are qualified by
     the dialog so a future non-modal reuse is not swept up. */
  dialog.modal_dialog .modal_content { background-color: #1c2128 !important; }
  dialog.modal_dialog .button_close_element,
  dialog.modal_dialog .button_close_icon { color: #c4cdd6 !important; }
  dialog.modal_dialog .button_close_icon svg path { stroke: #c4cdd6 !important; }
  /* The dropdown carets are inline <svg>s with `fill="currentColor"`, and the desktop
     variant sets that colour to pure black on the <svg> ITSELF, so an inherited value never
     reaches it — restate the fill on the path. */
  .nav_links_svg svg { color: #c4cdd6 !important; }
  .nav_links_svg svg path { fill: #c4cdd6 !important; }
  /* The Khan wordmark here (and its narrow twin and the footer lockup) is a single-colour
     `currentColor` mark, so the plain `a { color }` rule would tint it link-blue and
     `a:hover`, out-specifying a bare class, would flip it under the cursor. */
  .nav_desktop_logo, .nav_mobile_logo, .footer_logo_wrap { color: #e6edf3 !important; }
  /* Every anchor in the Webflow footer, the `currentColor` social marks included, inherits
     its colour from `.footer_wrap`; a direct declaration beats an inherited one whatever its
     importance, so the plain `a { color }` rule would turn the whole footer blue. Native
     hover changes no colour. */
  .footer_wrap a { color: #e6edf3 !important; }
  /* The dropdown panels are the same inherited-ink shape as the footer: one neutral ink on
     the panel, ~50 entries inheriting it, so the plain `a { color }` rule wins the lot. The
     group headers declare their own tone. */
  .nav_dropdown_main_content a { color: #e6edf3 !important; }
  /* Webflow gives each menu entry and CTA an overlay ring of
     `border: 1-2px solid transparent`, which the blanket `* { border-color }` reset would box
     on all four sides. Both classes are ring-only. */
  .nav_group_link, .button_main_border { border-color: transparent !important; }
  /* …except on the SECONDARY variant, where that overlay is the only element with a border
     width at all (`.button_main_element` is 0px), so it carries the outline the dark fill
     needs. */
  .button_main_border[class*="w-variant-e85564cd"] { border-color: #3a424c !important; }
  .nav_dropdown_main_content, .nav_dropdown_main_scroll, .nav_skip_wrap,
  .tab_button_item, .tab_content_list, .card_testimonial_inner,
  .card_primary_element { background-color: #1c2128 !important; }
  /* /schools curriculum chips: palest-blue fill with page-ink labels, serialised as
     `color(srgb …)`, which a channel-parsing audit skips. Khan's hover cue is the chip LOSING
     its fill, so an unqualified `!important` fill would erase the cue. */
  .catalog_item_wrap { background-color: #1c2128 !important; }
  .catalog_item_wrap:hover { background-color: transparent !important; }
  .catalog_item_text {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* Full-bleed decorative section bands. Despite the name not small shapes — 1268px wide
     under `.u-cover-absolute`, i.e. section backdrops. The child combinator keeps this off a
     genuinely small `.graphic_shape_wrap`. */
  .u-cover-absolute > .graphic_shape_wrap { background-color: #14181d !important; }
  /* The /schools hero's street map is an inline <svg> whose "roads" are
     `stroke="currentColor"`, and nothing else here touches an SVG stroke. Restating `color`
     is enough (the strokes inherit it); the coloured markers are literal fills. */
  .graphic_map_lines { color: #232a34 !important; }
  /* Webflow's hairlines are 1px DIVs with a light background, so the blanket border reset
     never reaches them. `.nav_button_line` is NOT in this family — its background is
     `currentColor` and already tracks the ink. */
  .c-divider, .nav_links_line, .nav_seasonal_line { background-color: #2d333b !important; }
  /* Text Webflow colours directly rather than inheriting, so the global `html, body` ink
     misses it. The stat cards are deliberately NOT lifted: they keep their coloured fills, so
     near-black is still correct there. */
  .nav_skip_text { color: #e6edf3 !important; }
  .card_testimonial_quote, .card_testimonial_author_name,
  .card_testimonial_author_title { color: #c4cdd6 !important; }
  .nav_group_title { color: #9aa4af !important; }
  /* The coloured cards Webflow KEEPS its fill on are the one place here where near-black ink
     is still RIGHT, and the global `h1-h6` / `p, li, …` block repaints it near-white. The
     captions are rich-text `<p>`s INSIDE the wrapper, so the wrapper's own colour never
     reaches them. `-webkit-text-fill-color` too, since the global bold rule sets it. */
  .card_stat_inner, .card_stat_inner *,
  .card_large_wrap, .card_large_wrap * {
    color: #191918 !important;
    -webkit-text-fill-color: #191918 !important;
  }
  /* Webflow's text-link button keeps the light page's near-black ink on the surface
     darkened above. Natively the strongest ink on the card, so it maps to the strong ink,
     not the link blue. */
  .button_link_element, .button_link_text { color: #e6edf3 !important; }
  /* Webflow's SECONDARY variant is a pale-blue pill with a purple label; same treatment as
     the Wonder Blocks `secondary` search button. Matched on the Webflow variant id, which
     marks ONLY this variant (the solid primary carries no variant class). */
  .button_main_element[class*="w-variant-e85564cd"],
  .button_toggle_element[class*="w-variant-ab355ea0"] {
    background-color: #1c2128 !important;
    border-color: #3a424c !important;
  }
  .button_main_element[class*="w-variant-e85564cd"] .button_main_text,
  .button_toggle_element[class*="w-variant-ab355ea0"] .button_toggle_icon {
    color: #a5a1ff !important;
    -webkit-text-fill-color: #a5a1ff !important;
  }
  /* Press / district logo bands: flat greyscale wordmarks drawn for the white section, so a
     straight inversion is faithful. `lighten` makes it safe on the marks shipping an OPAQUE
     white plate rather than alpha — inverting those gives a #000 rectangle darker than the
     band; the blend snaps anything below the band colour back to it, so no per-file exception
     list is needed. The wrapper fill is load-bearing: `.section_contain` is a stacking
     context, so the blend has no backdrop unless the band colour is painted INSIDE it. */
  .item_logo_wrap { background-color: #14181d !important; }
  .item_logo_wrap .item_logo_image {
    filter: invert(1) !important;
    mix-blend-mode: lighten !important;
  }

  /* The /about bar chart's axis TITLES are baked bold black into a flat alpha-ground raster,
     and it sits outside `#main-content`. The invert lifts those titles, but the four bars are
     a SEQUENTIAL blue ramp whose palest step inverts below the #14181d ground, where a bar
     reads as a hole; the trailing chain is the floor. The invariant on any retune is per-step
     pixels: all four bars above the ground, ordered, adjacent steps at least as far apart as
     natively (1.47 / 1.38 / 1.16). The stem is anchored so it cannot swallow
     `…_graphic.avif`. */
  img[src$="_graph.avif"] {
    filter: invert(1) hue-rotate(180deg) contrast(0.62) brightness(1.2) saturate(1.4) !important;
  }

  /* Hardcoded light surfaces that bypass the design tokens */
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background-color:#fff"],
  [style*="background-color: #fff"],
  [style*="background-color: var(--wb-semanticColor-core-foreground-knockout"] {
    background-color: #1c2128 !important;
  }

  /* The app shell's "trouble loading external resources" notice is hidden from Khan's own
     stylesheet and painted from an INLINE `background` — the one surface that survives when
     that stylesheet fails, while this theme still paints its text light. Dark red because the
     tint carries "something is wrong". Surface only: a `color` here loses to
     `.bibliotron-header div`. */
  .external-styles-missing { background-color: #2b1d1e !important; }

  /* …but that first substring also matches Perseus widget wrappers, whose inline style
     declares the CUSTOM PROPERTY `--perseus-widget-background-color: rgb(255, 255, 255)` —
     the match is a substring of the property NAME plus value. An opaque Perseus wrapper
     covers the MathJax the answer choices render on. Keep every carrier transparent and
     re-tone the variable itself; an `!important` author declaration outranks a non-important
     inline one. */
  [style*="--perseus-widget-background-color"] {
    background-color: transparent !important;
    --perseus-widget-background-color: #14181d !important;
  }

  /* Content-area neutralizer for surfaces hardcoding white or pale blue through hashed
     atomic classes. No `!important`, so it overrides those non-important backgrounds while
     yielding to the token-driven dark surfaces and the `!important` rules below.
     `background-image: none` also kills the white scroll-fade gradient at the foot of the
     unit sidebar; Khan paints no decorative gradients in `#main-content`.
     `:not(span)` is essential: mastery legend keys and progress-grid markers are icon
     `<span>`s whose `mask-image` FILL is their own `background-color`.
     The `var(--tile-color, transparent)` fallback keeps the mastery swatches coloured; a flat
     `transparent` collapses all four states to one grey square. Khan sets `--tile-color` only
     there. */
  #main-content [class]:not(span) { background-color: var(--tile-color, transparent); }
  /* The `background-image` half is split off to carve out ONE case: the CS scratchpad's
     Documentation panel draws its shape previews from a shared sprite with a per-entry inline
     `background-position-y`, which is the sprite's signature. */
  #main-content [class]:not(span):not([style*="background-position"]) { background-image: none; }
  /* That sprite is black line art with pale fills on an OPAQUE white sheet, so it needs the
     same inversion the CDN diagrams get. 0.92 rather than a full invert because the sheet
     dominates each tile: a full invert lands on #000, while 0.92 lands #141414, within a
     shade of the page base. */
  #main-content [style*="background-position"] {
    filter: invert(0.92) hue-rotate(180deg);
  }
  /* Re-surface the elements that NATIVELY carry a background, and only those — keyed on what
     the element looks like, not on its type. No button without a Wonder Blocks `data-kind`
     has a native background; `tertiary` is Khan's link-styled button (transparent at rest AND
     on hover), `secondary` the white-filled one. Painting by element type turns inline
     `tertiary` link-buttons into grey pills mid-sentence and flattens Perseus's answer tiles.
     It cannot leak a light surface: the neutralizer above already flattened everything. */
  /* `a[data-kind="secondary"]` for the same reason the primary rule matches on the attribute:
     Khan renders the kind as an <a> wherever the CTA navigates, so `button` alone leaves half
     the component unfilled. */
  #main-content button[data-kind="secondary"],
  #main-content a[data-kind="secondary"],
  #main-content a[class][role],
  #main-content [role="button"] { background-color: #1c2128; }
  #main-content button[data-kind="secondary"]:hover,
  #main-content a[data-kind="secondary"]:hover,
  #main-content a[class][role]:hover,
  #main-content [role="button"]:hover { background-color: #232a32; }
  /* Home testimonial video: the play affordance is an indigo disc holding a white mask-icon
     triangle, which the neutralizer flattens. The accessible name is the stable hook,
     `> div > div` the disc. Must out-rank the `[class]:not(span)` neutralizer (1,1,1), so keep
     the element types. */
  #main-content button[aria-label^="Play video"] > div > div { background-color: #2563c9; }
  #main-content button[aria-label^="Play video"]:hover > div > div { background-color: #2f6fd6; }

  /* Khan's list ROWS — course-unit rail, lesson rail, search result card — are anchors whose
     only hover affordance is a fill, and the neutralizer flattens BOTH states. Restore the
     hover fill only. Needs `!important` because the neutralizer carries `#main-content`.
     Scoped to the three row containers: a blanket `a:hover` would plate every inline text
     link. The search card has no test id, so it goes through `.search_results`;
     `ul > li > div > a` alone would also match the scratchpad sprite thumbnails, which have no
     hover fill. */
  nav[data-testid="course-unit-sidebar"] a:hover,
  [data-testid="learnable-content-cells"] a:hover,
  .search_results ul > li > div > a:hover { background-color: #1c2128 !important; }

  /* Home testimonial trio: the three cards are colour-coded with the light-page ink on top,
     and the neutralizer flattens them to identical grey boxes. As with the marketing stat
     tiles, on a coloured tile near-black is still RIGHT. Hashed vanilla-extract classes, so
     degrade-safe. */
  #main-content li._14s0xxx { background-color: #fcc539; }   /* Administrator */
  #main-content li._186c56yx { background-color: #72bb82; }  /* Teacher */
  #main-content li._1yar44ex { background-color: #f97b4f; }  /* Families */
  #main-content li._14s0xxx, #main-content li._14s0xxx *,
  #main-content li._186c56yx, #main-content li._186c56yx *,
  #main-content li._1yar44ex, #main-content li._1yar44ex * {
    color: #151521 !important;
    -webkit-text-fill-color: #151521 !important;
  }

  /* Mastery colour key (course legend + progress grid). Each state is a literal background /
     border colour on a hashed atomic class, so the neutralizer's
     `var(--tile-color, transparent)` fallback no longer catches these swatches and the blanket
     border reset greys their outline. Khan's own tones, so the legend matches its key. The
     class is shared by the legend swatch AND every grid tile in that state. Degrade-safe: a
     re-hash returns them to grey. */
  /* The fill needs the `[role="img"]` swatch ancestor to clear the neutralizer's
     `:not(span)` specificity, which the bare class does not. */
  #main-content [role="img"] ._lm0f0w6 { background-color: #594094; }   /* Mastered fill */
  #main-content [role="img"] ._y98xse6 { background-color: #948ebe; }   /* Proficient fill */
  #main-content [role="img"] ._1xgmyl25 { background-color: #d77d0f; }  /* Familiar fill */
  #main-content [role="img"] ._15ntp7j5 { background-color: #c66024; }  /* Attempted fill */
  #main-content ._hj9piv9 { border-color: #594094 !important; }   /* Mastered outline */
  #main-content ._1akjgsg9 { border-color: #948ebe !important; }  /* Proficient outline */
  #main-content ._1hupj7i9 { border-color: #d77d0f !important; }  /* Familiar outline */
  #main-content ._88nb8z9 { border-color: #c66024 !important; }   /* Attempted outline */

  /* "Up next for you:" card: a 4px brand-blue top rule the blanket border reset would repaint
     on all four sides. Restore the top edge only. Two test ids, one component:
     `mastery-practice-content-item` (unit) and the older `course-challenge-card` (course). */
  [data-testid="mastery-practice-content-item"],
  [data-testid="course-challenge-card"] { border-top-color: #5fb0e6 !important; }
  /* The course page's own "Up next for you:" draws that accent as a separate 4px DIV, not a
     border, so the neutralizer is what reaches it. No test id and no un-hashed class; the
     element type lifts this above the neutralizer's specificity. */
  #main-content div._x7kvevl { background-color: #5fb0e6 !important; }
  /* The recommended mastery-grid tile carries a 2px brand-blue ring on a pale plate, the
     only cue separating it from the "not started" tiles. The ring is border-reset territory,
     the plate the neutralizer's. */
  #main-content a[data-testid="m8z-unfy-item"] {
    border-color: #5fb0e6 !important;
    background-color: #18222f;
  }

  /* The "Level N" bar's progress knob is Khan's mastery purple over an unfilled track, and
     the neutralizer flattens it to a hollow ring. Only the knob carries colour. Hashed class,
     degrade-safe. */
  #main-content ._6cduun3 { background-color: #9059ff !important; }

  /* …but the neutralizer strips the fill off the PRIMARY call-to-action. Match on the
     ATTRIBUTE, not `button[data-kind]`: Khan renders the primary kind as an `<a>` wherever the
     CTA navigates, and keying on element type leaves every navigating CTA with no button
     affordance. */
  [data-kind="primary"] { background-color: #2563c9 !important; }
  [data-kind="primary"]:hover { background-color: #2f6fd6 !important; }
  /* An anchor CTA's label lives in a child span the shell rule paints near-white — what we
     want on the blue fill. */
  #main-content a[data-kind="primary"],
  #main-content a[data-kind="primary"] span { color: #ffffff !important; }
  /* …and a disabled primary must stay inert, so these need at least the specificity of the
     `#main-content` rule above, not just !important. */
  #main-content [data-kind="primary"][aria-disabled="true"],
  #main-content [data-kind="primary"]:disabled,
  [data-kind="primary"][aria-disabled="true"],
  [data-kind="primary"]:disabled {
    background-color: #2d333b !important;
    color: #8b949e !important;
  }

  /* Search-facet checkboxes: the checked box is brand blue under a white tick, and the
     neutralizer flattens it, leaving a glyph in an empty outline. */
  #main-content input[type="checkbox"]:checked { background-color: #2563c9 !important; }

  /* Problem-progress dots: a ring <div>, brand-blue bordered, FILLED the same blue on the
     current problem. The blanket border reset greys every ring and the neutralizer flattens
     the current fill. Which dot is current lives ONLY in `aria-current`; the class list is
     identical either way. The fill needs no `!important` (it only outranks the neutralizer),
     the ring does. */
  #main-content ul.indicatorContainer button[aria-label] > div {
    border-color: #5fb0e6 !important;
  }
  #main-content ul.indicatorContainer button[aria-current="true"] > div {
    background-color: #5fb0e6;
  }
  /* The exercise page draws a SECOND progress strip keyed by
     `data-testid="exercise-progress-N-<state>"`, encoding state by SHAPE — hollow ring
     unanswered, solid disc answered-wrong, 12px for current — all in the light-page ink, so
     restating them takes two properties. */
  [data-testid^="exercise-progress-"][data-testid*="-incomplete"] {
    border-color: #5fb0e6 !important;
  }
  /* The disc: an answered marker has NO border, so the neutralizer flattening its fill
     leaves nothing at all. Same blue as the ring, so filled = done / hollow = to do survives
     as Khan draws it. */
  [data-testid^="exercise-progress-"][data-testid$="-incorrect"],
  [data-testid^="exercise-progress-"][data-testid$="-incorrect-current"] {
    background-color: #5fb0e6 !important;
  }
  /* A CORRECT problem is the one marker Khan does not draw in the neutral ink: a `mask-image`
     tick <span> in brand green, the only thing distinguishing right from merely answered.
     Khan's green measures 5.3:1 on the page base, so it is restated verbatim; the `!important`
     holds it against the icon-span rules below. `-incorrect` cannot match `$="-correct"`,
     keeping the rules disjoint. */
  [data-testid^="exercise-progress-"][data-testid$="-correct"],
  [data-testid^="exercise-progress-"][data-testid$="-correct-current"] {
    background-color: #00a60e !important;
  }

  /* Wonder Blocks renders a button's leading icon as an EMPTY <span> whose `mask-image` is
     filled by its own background-color, resolving to the button's `currentColor` — hardcoded
     to the light-page ink on Khan's icon buttons. `:empty` distinguishes an icon span from a
     label span; a non-icon empty span has no size. */
  #main-content button > span:first-child:empty { background-color: #c4cdd6 !important; }
  /* …but an icon-ONLY `tertiary` is a link rendered as a glyph, which Khan paints brand blue,
     not the neutral icon grey above. `:first-child:last-child` marks icon-only. Needs
     `#main-content` to outrank the id above. */
  #main-content button[data-kind="tertiary"] > span:first-child:last-child:empty {
    background-color: #5fb0e6 !important;
  }

  /* Lesson-list content-type icons are inline <svg> hardcoding Khan's near-black ink
     (`fill="#21242c"` plus a 50%-alpha variant), invisible to a background-color audit. Remap
     the two ink values only. */
  #main-content [fill="#21242c"] { fill: #c4cdd6 !important; }
  #main-content [fill="rgba(33,36,44,0.50)"] { fill: rgba(196, 205, 214, 0.5) !important; }
  /* The "Community questions" marker is a third hardcoded ink in the same family — a
     speech-bubble <svg> at #3B3E40. */
  #main-content [fill="#3B3E40"] { fill: #c4cdd6 !important; }

  /* The home "Key supporters" band is not an HTML box: a full-bleed <svg> whose
     `<path fill="#F5F5F5">` draws the angled backdrop. No element computes a light background,
     so an element-bg scan passes clean while a white slab renders. */
  svg path[fill="#F5F5F5"] { fill: #14181d !important; }
  /* …and the supporter marks are dark-grey artwork drawn for that slab, so once it goes dark
     they must be inverted. Flat greyscale wordmarks, so a straight inversion is faithful. */
  img[src*="supporters-logos"] { filter: invert(1) !important; }

  /* Two raster illustrations with OPAQUE white baked into the pixels (lossy WebP, no alpha),
     so only a filter reaches it; `invert(1) hue-rotate(180deg)` flips lightness and returns
     each hue roughly to where it started. Only these two — the 404 scene, login collage and
     hero screenshots are drawn ON dark or genuinely depict the light product.
     1. Home subject chips. Eleven of the thirteen are opaque plates, whose inverted ground
     lands on #000, darker than the page: `mix-blend-mode: lighten` snaps those pixels back.
     The blend resolves against the nearest stacking context and this `<nav>` is one, so its
     backdrop is empty unless the page colour is painted INSIDE it — hence the fill on the nav,
     invisible alone. */
  nav[aria-labelledby="course-list-section-heading"] { background-color: #14181d !important; }
  nav[aria-labelledby="course-list-section-heading"] img {
    filter: invert(1) hue-rotate(180deg) !important;
    mix-blend-mode: lighten !important;
  }
  /* …except two of the thirteen: the Science flask and ELA speech bubble ship transparent, so
     there is nothing to knock out and the inversion only mangles the glyph; with no inversion
     there is no black ground, so the blend goes off with it. Filename stem, stable across the
     CDN hash. */
  nav[aria-labelledby="course-list-section-heading"] img[src*="flask"],
  nav[aria-labelledby="course-list-section-heading"] img[src*="message_bubble"] {
    filter: none !important;
    mix-blend-mode: normal !important;
  }
  /* Yellow is the one hue `hue-rotate(180deg)` cannot round-trip — a linear matrix
     approximation whose inverse maps back to orange-brown. The flask dodges that by not
     inverting; this starburst is a plate with no alpha, so it must invert and the hue is
     corrected on the way back. Tuned against native pixels measured AFTER the blend (which
     floors blue at the page's 29): rgb(255,184,29) against a native rgb(253,185,0). The plate
     is achromatic, so the blend still clears it. */
  nav[aria-labelledby="course-list-section-heading"] img[src*="badge"] {
    filter: invert(1) hue-rotate(195deg) saturate(2) brightness(2.2) !important;
  }
  /*  2. The logged-out home hero (one responsive asset; every srcset entry shares the
     `lohp_hero_graphic_mobile` stem). Its cream "graph paper" ramp is the largest bright shape
     above the fold. */
  img[src*="hp_hero_graphic_mobile"] {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Article and exercise diagrams: files on Khan's content CDN dropped in as `<img>`, so no
     rule here reaches their internals, and every one is drawn for the white page (transparent
     backdrop, `stroke="#000000"` linework). Matched on the CDN BUCKET as a substring, covering
     both the `cdn.kastatic.org/<bucket>/` and legacy `<bucket>.s3.amazonaws.com/` forms. Only
     two buckets hold line art alone: `ka-perseus-graphie`, `.svg` and `.png` alike, hence no
     extension filter, and `ka-content-images`, `.svg` only, since it also carries uploaded
     photos and photographs are never SVG. NOT covered, both damaged by inverting:
     `ka-perseus-images` (opaque figures and photographs) and Khan's product art under
     `/images/`, learner avatars included. */
  #main-content img[src*="ka-perseus-graphie"],
  #main-content img[src*="ka-content-images"][src$=".svg"] {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Search-result content-type icons: a `mask-image` SVG on a span inside a ringed circle,
     coloured through the span's `background-color` (natively a dark ink), which the neutralizer
     also flattens. Deterministic vanilla-extract class, degrade-safe. */
  ._1yakn8cj span { background-color: #8b949e !important; }

  /* Mastery "information" glyphs are the same `mask-image` pattern hardcoded to a dark ink.
     Scoped to the stable accessible name, not a hashed class. */
  #main-content span[role="img"][aria-label="Mastery information"] { background-color: #8b949e !important; }

  /* Logged-out donation widget (form/fieldset of amount + frequency options render on
     white) — neutralized via its stable form structure. */
  form fieldset, form fieldset ul, form fieldset li,
  form fieldset li label { background-color: #1c2128 !important; color: #c4cdd6 !important; }
  form fieldset li label:hover { background-color: #232a32 !important; }
  /* The picked gift frequency and amount are signalled by a white label with brand-blue text,
     and the state lives on a visually-hidden radio, so the label's class list is byte-identical
     in both states. The radio is the label's immediate previous sibling, so `:checked + label`
     reaches it without a parent selector (which the userstyles.org parser rejects). Scoped to
     `.choice-input`: the `.frequency-input` radios draw a real dot and are natively
     unfilled. */
  form fieldset input.choice-input:checked + label,
  form fieldset input.choice-input:checked + label:hover {
    background-color: #2563c9 !important;
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  /* Social sign-in buttons keep each provider's mark, but Apple's is a solid black glyph
     built for the white button. Only Apple's is inverted. */
  button[aria-label="Continue with Apple"] svg path { fill: #e6edf3 !important; }

  /* OneTrust consent banner: the stock CMP hardcodes white / near-black and is not
     token-driven, so it bypasses every remap above. The filled Accept/Allow/Confirm CTAs are
     natively dark charcoal with white text and are left alone. */
  #onetrust-consent-sdk #onetrust-banner-sdk,
  #onetrust-consent-sdk #onetrust-pc-sdk,
  #onetrust-consent-sdk .ot-sdk-container,
  #onetrust-consent-sdk .ot-pc-footer { background-color: #1c2128 !important; }
  #onetrust-consent-sdk #onetrust-policy-title,
  #onetrust-consent-sdk #onetrust-policy-text,
  #onetrust-consent-sdk .ot-b-addl-desc,
  #onetrust-consent-sdk #onetrust-banner-sdk *:not(a):not(button) { color: #e6edf3 !important; }
  #onetrust-consent-sdk #onetrust-banner-sdk a { color: #5fb0e6 !important; }
  #onetrust-consent-sdk #onetrust-pc-btn-handler,
  #onetrust-consent-sdk .ot-pc-refuse-all-handler {
    background-color: #1c2128 !important;
    color: #5fb0e6 !important;
    border-color: #3a424c !important;
  }
  /* Preference centre: its description, close button and "Always Active" label keep
     light-page inks, and the "Powered by OneTrust" strip a hardcoded #f4f4f4 panel. */
  #onetrust-consent-sdk #ot-pc-desc,
  #onetrust-consent-sdk #ot-pc-desc * { color: #c4cdd6 !important; }
  #onetrust-consent-sdk #close-pc-btn-handler { color: #9aa4af !important; }
  #onetrust-consent-sdk .ot-always-active { color: #5fb0e6 !important; }
  #onetrust-consent-sdk .ot-pc-footer-logo { background-color: #1c2128 !important; }
  /* Surfaces the preference centre only creates on an interaction: `.ot-acc-grpcntr`, a
     category's description body, hidden until its accordion opens; `#ot-sel-blk`, the "Cookie
     List" screen; `.ot-optout-signal`, shown only under a Global Privacy Control signal. */
  #onetrust-consent-sdk .ot-acc-grpcntr,
  #onetrust-consent-sdk .ot-acc-txt,
  #onetrust-consent-sdk #ot-sel-blk,
  #onetrust-consent-sdk #ot-fltr-cnt,
  #onetrust-consent-sdk .ot-optout-signal { background-color: #1c2128 !important; }
  /* Those four panels are the only place OneTrust puts its near-black ink on a plate rather
     than on the modal, so darkening them is what makes the ink dark-on-dark. The filter panel's
     "Apply" / "Cancel" siblings are natively dark and need nothing. */
  #onetrust-consent-sdk #ot-sel-blk .ot-consent-hdr,
  #onetrust-consent-sdk #ot-sel-blk .ot-li-hdr,
  #onetrust-consent-sdk #clear-filters-handler,
  #onetrust-consent-sdk .ot-optout-signal,
  #onetrust-consent-sdk .ot-optout-signal * { color: #c4cdd6 !important; }
  /* Both OneTrust wordmarks are solid-black artwork drawn for a white modal. */
  #onetrust-consent-sdk .ot-pc-logo,
  #onetrust-consent-sdk .ot-pc-footer-logo img { filter: invert(1) !important; }
  /* `#ot-anchor` is a pure CSS triangle: a 0x0 box whose four 12px borders are all
     `transparent`, which the blanket `* { border-color }` rule below would repaint into a
     solid 24px diamond. */
  #onetrust-consent-sdk #ot-anchor { border-color: transparent !important; }
  /* The weekly-streak counter is a `border: 1px solid transparent` box the blanket rule would
     box in grey. `div[tabindex]` is its shape there — its only focusable siblings are an <h2>
     and an icon <span>. */
  .stp-animated-banner div[tabindex] { border-color: transparent !important; }
  /* That banner's progress popover renders into a body-level portal, outside `#main-content`.
     Only the empty-state box, a literal light background on a hashed class, needs its own
     surface. `[data-placement]` separates a Popper-anchored Popover from the app's modal
     dialogs (the Share sheet is `aria-modal`, no placement), "Close Popover" is the fixed close
     label, and the box is the sibling after the table's wrapper — so a populated table keeps
     its own fills. */
  [role="dialog"][data-placement] button[aria-label="Close Popover"] + div > div > div + div {
    background-color: #1c2128 !important;
  }

  /* Soften any remaining bright borders across the app */
  * { border-color: #2d333b !important; }

  /* Form validation state (login / signup LabeledField): Khan reddens the invalid input's
     border, the "Error:" mask icon and the helper text, all through the critical token, and
     the blanket border reset, the shell `span` rule and the `p { color }` block flatten every
     one of them to neutral. `aria-invalid` and the `-error` live region are Wonder Blocks'
     stable contract; the login server error (`#log-in-server-error`) is the same shape with
     its own id. Lifted red so the text passes on the page base, where Khan's #d92916 does
     not. Placed after the blanket reset because the input border rule ties it on
     specificity. */
  input[aria-invalid="true"], textarea[aria-invalid="true"] { border-color: #ff7b72 !important; }
  div[id$="-error"][aria-live] p,
  #log-in-server-error p { color: #ff7b72 !important; }
  span[role="img"][aria-label="Error:"],
  #log-in-server-error span:empty {
    background-color: #ff7b72 !important;
    color: #ff7b72 !important;
  }

  /* Code editor / syntax highlighting (CS & programming courses)
     CodeMirror + ka-syntax tokens */
  .CodeMirror, .CodeMirror-gutters,
  pre, code, .highlight, .codehilite {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
  }
  .CodeMirror-gutters { border-color: #2d333b !important; }
  .CodeMirror-linenumber { color: #6e7681 !important; }
  .cm-comment { color: #8b949e !important; }
  .cm-keyword, .cm-builtin { color: #ff7b72 !important; }
  .cm-string, .cm-string-2 { color: #a5d6ff !important; }
  .cm-number, .cm-atom { color: #79c0ff !important; }
  .cm-variable, .cm-variable-2, .cm-property { color: #e6edf3 !important; }
  .cm-def, .cm-tag { color: #7ee787 !important; }
  .cm-attribute { color: #79c0ff !important; }
  .cm-operator { color: #c4cdd6 !important; }

  /* Khan's "scratchpad" editor is ACE (`.ace_editor.ace-tm`), not CodeMirror, so the palette
     above never reaches it; its light "tm" token colours are built for white, and the generic
     span rule flattens them to one grey. */
  .ace_editor, .ace_editor .ace_gutter, .ace_editor .ace_scroller {
    background-color: #0d1117 !important;
  }
  .ace_editor, .ace_editor .ace_gutter-cell { color: #e6edf3 !important; }
  .ace_editor .ace_comment { color: #8b949e !important; }
  .ace_editor .ace_keyword, .ace_editor .ace_storage { color: #ff7b72 !important; }
  .ace_editor .ace_string { color: #a5d6ff !important; }
  .ace_editor .ace_constant, .ace_editor .ace_constant.ace_numeric,
  .ace_editor .ace_constant.ace_language, .ace_editor .ace_constant.ace_buildin {
    color: #79c0ff !important;
  }
  .ace_editor .ace_support.ace_function,
  .ace_editor .ace_entity.ace_name.ace_function { color: #d2a8ff !important; }
  .ace_editor .ace_support.ace_type, .ace_editor .ace_support.ace_class,
  .ace_editor .ace_support.ace_constant { color: #79c0ff !important; }
  .ace_editor .ace_variable, .ace_editor .ace_identifier { color: #e6edf3 !important; }
  .ace_editor .ace_keyword.ace_operator, .ace_editor .ace_punctuation,
  .ace_editor .ace_paren { color: #c4cdd6 !important; }
  .ace_editor .ace_invalid { color: #ffa198 !important; }
  /* Cursor + line/selection chrome (the universal border rule otherwise dims the caret
     to #2d333b). */
  .ace_editor .ace_cursor { color: #e6edf3 !important; border-left-color: #e6edf3 !important; }
  .ace_editor .ace_marker-layer .ace_active-line,
  .ace_editor .ace_gutter-active-line { background-color: #161b22 !important; }
  .ace_editor .ace_marker-layer .ace_selection { background-color: #2d4f7c !important; }
  .ace_editor .ace_print-margin { background-color: #21262d !important; }

  /* Challenge hint code (`pre.rainbowjs`, Rainbow.js tokens) beside the ACE editor: a
     light-page palette on white that the generic `pre, code` ink and the span-inherit rule
     flatten to one white. Same token colours as the ACE block so the hint reads like the
     editor it is copied into. The token family is the site's own `.rainbowjs .<token>` set;
     `.function.call` has no site rule and keeps the base ink. */
  .rainbowjs .comment { color: #8b949e !important; }
  .rainbowjs .constant { color: #ff7b72 !important; }
  .rainbowjs .constant.numeric { color: #79c0ff !important; }
  .rainbowjs .storage, .rainbowjs .keyword, .rainbowjs .selector { color: #ff7b72 !important; }
  .rainbowjs .keyword.operator { color: #c4cdd6 !important; }
  .rainbowjs .string { color: #a5d6ff !important; }
  .rainbowjs .entity { color: #7ee787 !important; }
  .rainbowjs .entity.name.function { color: #d2a8ff !important; }
  .rainbowjs .support { color: #79c0ff !important; }
  .rainbowjs .variable.global, .rainbowjs .variable.class,
  .rainbowjs .variable.instance { color: #e6edf3 !important; }

  /* Scratchpad tablist: the current tab's 5px brand-blue `border-bottom` is repainted by the
     blanket border reset. Re-tint via its stable ARIA state. */
  #scratchpad-tabs [role="tab"][aria-selected="true"] { border-bottom-color: #5fb0e6 !important; }

  /* The CS editor's own tooltips are `.tooltip` divs rendered at the end of <body>, hidden
     until you interact with the code. The picker's panels are hardcoded white, and each tail is
     a REAL-ELEMENT CSS triangle — a 0x0 box with three 8px borders, two `transparent` — that
     the blanket border reset turns into a grey square. Restore the transparency, then tint only
     the visible edge. */
  .tooltip { background-color: #1c2128 !important; }
  .tooltip .current-media,
  .tooltip .media-groups,
  .tooltip .mediapicker-preview-content,
  .tooltip .image { background-color: #1c2128 !important; }
  .tooltip > .arrow {
    border-color: transparent !important;
    border-top-color: #1c2128 !important;
  }
  .tooltip.mediapicker > .arrow,
  .tooltip.mediapicker-preview > .arrow,
  .tooltip.picker > .arrow {
    border-top-color: transparent !important;
    border-right-color: #1c2128 !important;
  }
  /* The picker's full-size twin: `.tooltip.mediapicker` above is the hover grid, while "see
     all" opens a body-level `.modal.mediapicker-modal` with its own white sheet and footer,
     `display:none` until opened. Its sound rows are <audio> with the browser's own dark
     controls. The modal declares a mid grey that its bare-<span> file labels inherit and
     nothing else here reaches. */
  .modal.mediapicker-modal,
  .modal.mediapicker-modal .mediapicker-modal-footer { background-color: #1c2128 !important; }
  .modal.mediapicker-modal { color: #c4cdd6 !important; }

  /* The live editor's error bubble (`.tipbar`) floats over the program canvas, which the
     learner's own program paints and no rule here can reach. Hardcoded for a white page, so the
     neutralizer flattens its panel while the text rules lift the copy — white-on-white; it
     needs an opaque dark panel of its own. The `.quote` chips are <span>s the neutralizer
     deliberately skips, so they keep their white fill. The `.speech-arrow` and `.error-buddy`
     sprites are cleared by the neutralizer and deliberately left off — both are drawn for a
     light bubble. */
  .tipbar {
    background-color: #1c2128 !important;
    border-color: #3a424c !important;
    color: #e6edf3 !important;
  }
  .tipbar .quote {
    background-color: #0d1117 !important;
    border-color: #3a424c !important;
    color: #e6edf3 !important;
  }
  .tipbar .close { color: #9aa4af !important; text-shadow: none !important; }

  /* Worked-example math highlight colors (MathML `mathcolor`). Khan tints solution terms with
     a fixed white-page palette; remap each to a lighter shade of the SAME hue so the pairing
     survives. Targets the carrier and its descendants. */
  [mathcolor="#5D5F66"], [mathcolor="#5D5F66"] * { color: #9aa4af !important; -webkit-text-fill-color: #9aa4af !important; }
  [mathcolor="#D92916"], [mathcolor="#D92916"] * { color: #ff7b72 !important; -webkit-text-fill-color: #ff7b72 !important; }
  [mathcolor="#3D7586"], [mathcolor="#3D7586"] * { color: #6cb6d9 !important; -webkit-text-fill-color: #6cb6d9 !important; }
  [mathcolor="#0C7F99"], [mathcolor="#0C7F99"] * { color: #6cb6d9 !important; -webkit-text-fill-color: #6cb6d9 !important; }
  [mathcolor="#11ACCD"], [mathcolor="#11ACCD"] * { color: #79c0ff !important; -webkit-text-fill-color: #79c0ff !important; }
  [mathcolor="#208170"], [mathcolor="#208170"] * { color: #7ee787 !important; -webkit-text-fill-color: #7ee787 !important; }
  [mathcolor="#0D923F"], [mathcolor="#0D923F"] * { color: #7ee787 !important; -webkit-text-fill-color: #7ee787 !important; }
  [mathcolor="#7854AB"], [mathcolor="#7854AB"] * { color: #d2a8ff !important; -webkit-text-fill-color: #d2a8ff !important; }
  [mathcolor="#9D38BD"], [mathcolor="#9D38BD"] * { color: #d2a8ff !important; -webkit-text-fill-color: #d2a8ff !important; }
  [mathcolor="#CA337C"], [mathcolor="#CA337C"] * { color: #ff8ac4 !important; -webkit-text-fill-color: #ff8ac4 !important; }
  [mathcolor="#E07D10"], [mathcolor="#E07D10"] * { color: #f0a868 !important; -webkit-text-fill-color: #f0a868 !important; }
  /* PEMDAS colour-coding uses a second palette the block above misses: a deep purple
     ("Grouping", "Exponents") and a dark olive-gold (addition/subtraction). */
  [mathcolor="#594094"], [mathcolor="#594094"] *,
  [mathcolor="#8351E8"], [mathcolor="#8351E8"] * { color: #d2a8ff !important; -webkit-text-fill-color: #d2a8ff !important; }
  [mathcolor="#946700"], [mathcolor="#946700"] * { color: #e3b341 !important; -webkit-text-fill-color: #e3b341 !important; }
  /* MathJax v3 (articles) carries the highlight as an INLINE `color` on an <mjx-mstyle> and
     paints glyphs in `mjx-c::before` pseudo-elements that inherit it, so neither the
     `mathcolor` block above nor a text-colour audit of real elements sees it. */
  #main-content [style*="color: rgb(93, 95, 102)"] { color: #9aa4af !important; -webkit-text-fill-color: #9aa4af !important; }
  #main-content [style*="color: rgb(217, 41, 22)"] { color: #ff7b72 !important; -webkit-text-fill-color: #ff7b72 !important; }
  #main-content [style*="color: rgb(61, 117, 134)"] { color: #6cb6d9 !important; -webkit-text-fill-color: #6cb6d9 !important; }
  #main-content [style*="color: rgb(12, 127, 153)"] { color: #6cb6d9 !important; -webkit-text-fill-color: #6cb6d9 !important; }
  #main-content [style*="color: rgb(17, 172, 205)"] { color: #79c0ff !important; -webkit-text-fill-color: #79c0ff !important; }
  #main-content [style*="color: rgb(32, 129, 112)"] { color: #7ee787 !important; -webkit-text-fill-color: #7ee787 !important; }
  #main-content [style*="color: rgb(13, 146, 63)"] { color: #7ee787 !important; -webkit-text-fill-color: #7ee787 !important; }
  #main-content [style*="color: rgb(131, 81, 232)"] { color: #d2a8ff !important; -webkit-text-fill-color: #d2a8ff !important; }
  #main-content [style*="color: rgb(120, 84, 171)"] { color: #d2a8ff !important; -webkit-text-fill-color: #d2a8ff !important; }
  #main-content [style*="color: rgb(157, 56, 189)"] { color: #d2a8ff !important; -webkit-text-fill-color: #d2a8ff !important; }
  #main-content [style*="color: rgb(202, 51, 124)"] { color: #ff8ac4 !important; -webkit-text-fill-color: #ff8ac4 !important; }
  #main-content [style*="color: rgb(224, 125, 16)"] { color: #f0a868 !important; -webkit-text-fill-color: #f0a868 !important; }
  #main-content [style*="color: rgb(68, 122, 83)"] { color: #7ee787 !important; -webkit-text-fill-color: #7ee787 !important; }
  #main-content [style*="color: rgb(178, 80, 113)"] { color: #ff8ac4 !important; -webkit-text-fill-color: #ff8ac4 !important; }
  /* Inline-style twins of the PEMDAS colour-coding above. */
  #main-content [style*="color: rgb(89, 64, 148)"] { color: #d2a8ff !important; -webkit-text-fill-color: #d2a8ff !important; }
  #main-content [style*="color: rgb(148, 103, 0)"] { color: #e3b341 !important; -webkit-text-fill-color: #e3b341 !important; }
  /* A token-coloured term inside a bold run inherits the `b, strong` text-fill above, which
     paints over the term's colour; the fill must track that colour instead. */
  #main-content [style*="learning-math-foreground"] {
    -webkit-text-fill-color: currentColor !important;
  }

  /* The mastery bar's numerator is a <b> hardcoded to the light-page ink; no rule here
     reaches a bare <b>, the shell rule covering only a/span/div. */
  .fraction-skills-to-proficient-numerator { color: #e6edf3 !important; }

  /* Perseus answer-choice tints (muted green + mauve on multiple-choice math) hardcode
     white-page values. Lift each to the same-hue shade the worked-example set uses. */
  [mathcolor="#447A53"], [mathcolor="#447A53"] * { color: #7ee787 !important; -webkit-text-fill-color: #7ee787 !important; }
  [mathcolor="#B25071"], [mathcolor="#B25071"] * { color: #ff8ac4 !important; -webkit-text-fill-color: #ff8ac4 !important; }

  /* Article content tables: hardcoded pale cells on classless <td>/<th>, which the
     `#main-content [class]` neutralizer cannot reach. */
  #main-content table, #main-content thead, #main-content tbody,
  #main-content tr, #main-content td, #main-content th {
    background-color: transparent !important;
  }

  /* Perseus multiple-choice cards draw their frame / divider through `::before` + `::after`
     hardcoded to a light grey — invisible to an element-bg audit, bright white frames on
     screen. */
  .framework-perseus li::before,
  .framework-perseus li::after,
  .perseus-renderer li::before,
  .perseus-renderer li::after { background-color: #2d333b !important; }

  /* The donation-widget `form fieldset …` rule above also matches the Perseus choice
     <fieldset> (choices sit inside a <form>), painting it opaque; Perseus renders each choice's
     block math on a lower paint layer, so that fill covers the math. Higher specificity, so the
     donation widget is untouched. */
  .framework-perseus fieldset, .framework-perseus fieldset ul,
  .framework-perseus fieldset li, .framework-perseus fieldset li label,
  .perseus-renderer fieldset, .perseus-renderer fieldset ul,
  .perseus-renderer fieldset li, .perseus-renderer fieldset li label {
    background-color: transparent !important;
  }

  /* Perseus draws the answer-choice "card" edges by overlaying the choice <ul> with a
     `::before` whose background-COLOR is transparent but whose background-IMAGE is a hardcoded
     white gradient — read as transparent by every element-background audit. */
  .framework-perseus fieldset ul::before,
  .framework-perseus fieldset ul::after,
  .perseus-renderer fieldset ul::before,
  .perseus-renderer fieldset ul::after { background-image: none !important; }

  /* Perseus marks the picked answer ONLY through `aria-pressed="true"` on the A-E letter tile
     — its class list is byte-identical in both states. The interactive-card rule above outranks
     Perseus's own non-important selected-state rule, so without this both states are the same
     grey tile. Restore its second cue too: the picked choice's math is recoloured the same
     blue, which the blanket `li { color }` rule flattens. The choice content is the tile's only
     sibling, so `+ div` reaches it without a parent selector (which the userstyles.org parser
     rejects). Once submitted Perseus repaints the right tiles green, so `aria-disabled="true"`
     keeps that green. Specificity must clear `#main-content`'s id — `!important` alone loses to
     it. */
  /* The tile carries no `data-kind`, so the rule above leaves it unpainted; natively
     transparent with a mid-grey 2px outline the blanket border reset dims, it would be a bare
     floating letter. */
  #main-content .framework-perseus fieldset li > button[aria-pressed],
  #main-content .perseus-renderer fieldset li > button[aria-pressed] {
    background-color: #1c2128;
  }
  #main-content .framework-perseus fieldset li > button[aria-pressed="true"][aria-disabled="false"],
  #main-content .perseus-renderer fieldset li > button[aria-pressed="true"][aria-disabled="false"] {
    background-color: #2563c9 !important;
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  #main-content .framework-perseus fieldset li > button[aria-pressed="true"][aria-disabled="false"]:hover,
  #main-content .perseus-renderer fieldset li > button[aria-pressed="true"][aria-disabled="false"]:hover {
    background-color: #2f6fd6 !important;
  }
  /* Perseus's second cue is the choice TEXT, whose body is a nested stack of <div>s the
     page-shell rule paints near-white `!important`, so colouring the wrapper alone changes
     nothing. Only `div`/`span`/`b`/`strong`: MathML and MathJax emit custom elements and KaTeX
     carries term colours as an inline `color` on a span, none of which this reaches. */
  #main-content .framework-perseus fieldset li > button[aria-pressed="true"][aria-disabled="false"] + div,
  #main-content .perseus-renderer fieldset li > button[aria-pressed="true"][aria-disabled="false"] + div,
  #main-content .framework-perseus fieldset li > button[aria-pressed="true"][aria-disabled="false"] + div div,
  #main-content .perseus-renderer fieldset li > button[aria-pressed="true"][aria-disabled="false"] + div div,
  #main-content .framework-perseus fieldset li > button[aria-pressed="true"][aria-disabled="false"] + div span:not([style*="color"]),
  #main-content .perseus-renderer fieldset li > button[aria-pressed="true"][aria-disabled="false"] + div span:not([style*="color"]),
  #main-content .framework-perseus fieldset li > button[aria-pressed="true"][aria-disabled="false"] + div b,
  #main-content .perseus-renderer fieldset li > button[aria-pressed="true"][aria-disabled="false"] + div b,
  #main-content .framework-perseus fieldset li > button[aria-pressed="true"][aria-disabled="false"] + div strong,
  #main-content .perseus-renderer fieldset li > button[aria-pressed="true"][aria-disabled="false"] + div strong {
    color: #9bd4ff !important;
    -webkit-text-fill-color: #9bd4ff !important;
  }
  #main-content .framework-perseus fieldset li > button[aria-pressed="true"][aria-disabled="true"],
  #main-content .perseus-renderer fieldset li > button[aria-pressed="true"][aria-disabled="true"] {
    background-color: #0b7c18 !important;
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  /* The multi-select tick inside a picked tile is the empty-span mask icon, painted the
     neutral grey by the icon rule above; on the blue/green tile Perseus draws it white. */
  #main-content .framework-perseus fieldset li > button[aria-pressed="true"] > span:first-child:empty,
  #main-content .perseus-renderer fieldset li > button[aria-pressed="true"] > span:first-child:empty {
    background-color: #ffffff !important;
  }

  /* Scrollbars */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: #14181d; }
  ::-webkit-scrollbar-thumb { background: #2d333b; border-radius: 6px; }
  ::-webkit-scrollbar-thumb:hover { background: #3a424c; }
  /* The corner is a separate pseudo from the track: any element scrollable on BOTH axes
     (Perseus's question column at narrow widths) leaves a default-white square where the bars
     meet. */
  ::-webkit-scrollbar-corner { background: #14181d; }
}
